<?php require __DIR__.'/_layout_start.php'; ?><h1><?= (int)$row['id']?'Modifica catalogo':'Nuovo catalogo' ?></h1><?php foreach($errors as $er): ?><div class="error"><?= htmlspecialchars($er) ?></div><?php endforeach; ?><form method="post" enctype="multipart/form-data" action="/admin/content/catalogs/save"><input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrf) ?>"><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><div class="formgrid"><label>Titolo<input name="title" value="<?= htmlspecialchars($row['title']) ?>" required></label><label>Slug<input name="slug" value="<?= htmlspecialchars($row['slug']) ?>"></label><label class="full">Descrizione<textarea name="description" rows="5"><?= htmlspecialchars((string)$row['description']) ?></textarea></label><label>Anno<input type="number" name="document_year" value="<?= htmlspecialchars((string)$row['document_year']) ?>"></label><label>Ordine<input type="number" name="sort_order" value="<?= (int)$row['sort_order'] ?>"></label><label>Copertina<input type="file" name="cover_image" accept="image/jpeg,image/png,image/webp"><?php if(!empty($row['cover_image'])): ?><small>Attuale: <?= htmlspecialchars($row['cover_image']) ?></small><?php endif; ?></label><label>PDF catalogo<input type="file" name="pdf_file" accept="application/pdf"><?php if(!empty($row['pdf_path'])): ?><small>Attuale: <?= htmlspecialchars($row['pdf_path']) ?></small><?php endif; ?></label><label class="check"><input type="checkbox" name="published" value="1" <?= !empty($row['published'])?'checked':'' ?>> Pubblicato</label></div><p><button class="btn" type="submit">Salva</button></p></form><?php require __DIR__.'/_layout_end.php'; ?>